// The site's content, written by damasco: every page is a JSON file in
// content/pages, every picture's details a JSON file in content/media, every
// component (a part several pages share) a JSON file in content/components.
// The schemas are generated by damasco from schema/types at each build.
import { defineCollection } from 'astro:content'
import { glob } from 'astro/loaders'
import { componentSchema, mediaSchema, pageSchema } from '../.damasco/schema'

const pages = defineCollection({
  loader: glob({
    pattern: '*.json',
    base: './content/pages',
    generateId: ({ entry }) => entry.replace(/\.json$/, ''),
  }),
  schema: pageSchema,
})

const media = defineCollection({
  loader: glob({
    pattern: '*.json',
    base: './content/media',
    generateId: ({ entry }) => entry.replace(/\.json$/, ''),
  }),
  schema: mediaSchema,
})

const components = defineCollection({
  loader: glob({
    pattern: '*.json',
    base: './content/components',
    generateId: ({ entry }) => entry.replace(/\.json$/, ''),
  }),
  schema: componentSchema,
})

export const collections = { pages, media, components }
